import fs from "node:fs";
import path from "node:path";

const root = process.cwd();

const encodedFiles = {"lib/persistentQueryCache.ts": "", "lib/discoveryQueries.ts": "", "app/(root)/(tabs)/filtered-properties.tsx": "", "app/(root)/(student)/s-filtered-properties.tsx": "", "app/(root)/(tabs)/all-locations.tsx": "", "app/(root)/(student)/s-all-locations.tsx": "", "app/(root)/(tabs)/properties-by-location.tsx": "", "app/(root)/(student)/s-properties-by-location.tsx": "", "components/popularLocations.tsx": "", "app/(root)/(student)/s-explore.tsx": ""};

const decodeFile = (encoded) =>
  Buffer.from(encoded, "base64").toString("utf8");

const read = (relativePath) => {
  const absolutePath = path.join(root, relativePath);

  if (!fs.existsSync(absolutePath)) {
    throw new Error(
      `Missing required file: ${relativePath}\n` +
        "Run this script from the Nookly project root.",
    );
  }

  return fs.readFileSync(absolutePath, "utf8");
};

const replaceRequired = (
  text,
  pattern,
  replacement,
  label,
) => {
  if (typeof pattern === "string") {
    if (!text.includes(pattern)) {
      throw new Error(
        `Could not locate ${label}. No files were written.`,
      );
    }

    return text.replace(pattern, replacement);
  }

  if (!pattern.test(text)) {
    throw new Error(
      `Could not locate ${label}. No files were written.`,
    );
  }

  return text.replace(pattern, replacement);
};

// ===========================================================================
// Patch the Step 9 local useAppwrite hook.
// ===========================================================================
let useAppwrite = read("lib/useAppwrite.ts");

if (
  !useAppwrite.includes(
    'peekPersistentQueryCache',
  )
) {
  useAppwrite =
    'import { peekPersistentQueryCache } from "@/lib/persistentQueryCache";\n' +
    useAppwrite;
}

if (
  !useAppwrite.includes(
    "const getSynchronousCacheEntry",
  )
) {
  const inFlightPattern =
    /const inFlightRequests = new Map<\s*string,\s*Promise<unknown>\s*>\(\);\s*/m;

  useAppwrite = replaceRequired(
    useAppwrite,
    inFlightPattern,
`const inFlightRequests = new Map<
  string,
  Promise<unknown>
>();

const getSynchronousCacheEntry = <T,>(
  memoryKey: string,
  logicalKey: string,
  namespace: string,
): MemoryCacheEntry<T> | undefined => {
  const memoryEntry = memoryCache.get(
    memoryKey,
  ) as MemoryCacheEntry<T> | undefined;

  if (memoryEntry) {
    return memoryEntry;
  }

  const persistentEntry =
    peekPersistentQueryCache<T>(
      logicalKey,
      namespace,
    );

  if (!persistentEntry) {
    return undefined;
  }

  const hydratedEntry: MemoryCacheEntry<T> = {
    data: persistentEntry.data,
    timestamp: persistentEntry.savedAt,
  };

  memoryCache.set(memoryKey, hydratedEntry);
  return hydratedEntry;
};

`,
    "the shared in-flight request map",
  );
}

useAppwrite = replaceRequired(
  useAppwrite,
  /  const initialMemoryEntry = useMemo\(\s*\(\) =>\s*memoryCache\.get\(memoryKey\) as\s*\| MemoryCacheEntry<T>\s*\| undefined,\s*\[memoryKey\],\s*\);/m,
`  const initialMemoryEntry = useMemo(
    () =>
      getSynchronousCacheEntry<T>(
        memoryKey,
        logicalKey,
        namespace,
      ),
    [logicalKey, memoryKey, namespace],
  );`,
  "the Step 9 initial memory entry",
);

useAppwrite = replaceRequired(
  useAppwrite,
  /    const nextMemoryEntry = memoryCache\.get\(\s*memoryKey,\s*\) as MemoryCacheEntry<T> \| undefined;/m,
`    const nextMemoryEntry =
      getSynchronousCacheEntry<T>(
        memoryKey,
        logicalKey,
        namespace,
      );`,
  "the Step 9 query-key switch cache lookup",
);

useAppwrite = replaceRequired(
  useAppwrite,
  /\}, \[memoryKey, skip\]\);/,
  "}, [logicalKey, memoryKey, namespace, skip]);",
  "the query-key switch dependencies",
);

// ===========================================================================
// Patch Step 11 auth hydration so all persistent queries are warm before
// the authenticated routes render.
// ===========================================================================
let authStore = read("store/auth.store.ts");

if (
  !authStore.includes(
    "warmPersistentQueryCache",
  )
) {
  authStore =
    'import { warmPersistentQueryCache } from "@/lib/persistentQueryCache";\n' +
    authStore;
}

authStore = replaceRequired(
  authStore,
  /await warmProfilePageCache\(\s*normalizedUser\.accountId,\s*\);/m,
`await Promise.all([
        warmProfilePageCache(
          normalizedUser.accountId,
        ),
        warmPersistentQueryCache(
          normalizedUser.accountId,
        ),
      ]);`,
  "the Step 11 setUser profile-cache warmup",
);

authStore = replaceRequired(
  authStore,
  /await warmProfilePageCache\(\s*storedUser\.accountId,\s*\);/m,
`await Promise.all([
          warmProfilePageCache(
            storedUser.accountId,
          ),
          warmPersistentQueryCache(
            storedUser.accountId,
          ),
        ]);`,
  "the Step 11 hydration profile-cache warmup",
);

// ===========================================================================
// Patch regular Explore without replacing its existing UI.
// ===========================================================================
let explore = read(
  "app/(root)/(tabs)/explore.tsx",
);

explore = replaceRequired(
  explore,
  'import { getPropertiesWithFilters, PriceRange } from "@/lib/appwrite";',
  'import { config, getPropertiesWithFilters, PriceRange } from "@/lib/appwrite";',
  "the Explore Appwrite import",
);

explore = replaceRequired(
  explore,
  '    cacheKey: "map_pins_full",\n  });',
  `    cacheKey: "map_pins_full",
    watchCollections: [config.propertiesCollectionId],
  });`,
  "the Explore map cache block",
);

explore = replaceRequired(
  explore,
  /    params: filterParams,\s*cacheKey,\s*\}\);/m,
`    params: filterParams,
    cacheKey,
    watchCollections: [config.propertiesCollectionId],
  });`,
  "the Explore filtered query cache block",
);

// ===========================================================================
// Validate all generated and patched outputs before writing anything.
// ===========================================================================
const generated = Object.fromEntries(
  Object.entries(encodedFiles).map(
    ([relativePath, encoded]) => [
      relativePath,
      decodeFile(encoded),
    ],
  ),
);

const outputs = {
  ...generated,
  "lib/useAppwrite.ts": useAppwrite,
  "store/auth.store.ts": authStore,
  "app/(root)/(tabs)/explore.tsx":
    explore,
};

if (
  !outputs["lib/persistentQueryCache.ts"].includes(
    "warmPersistentQueryCache",
  ) ||
  !outputs["lib/persistentQueryCache.ts"].includes(
    "peekPersistentQueryCache",
  )
) {
  throw new Error(
    "Validation failed: cold-start query hydration is incomplete.",
  );
}

if (
  !useAppwrite.includes(
    "getSynchronousCacheEntry",
  ) ||
  !useAppwrite.includes(
    "peekPersistentQueryCache",
  )
) {
  throw new Error(
    "Validation failed: useAppwrite cannot synchronously consume warmed queries.",
  );
}

if (
  !authStore.includes(
    "warmPersistentQueryCache",
  )
) {
  throw new Error(
    "Validation failed: auth does not prewarm persistent queries.",
  );
}

const requiredDiscoveryFiles = [
  "app/(root)/(tabs)/filtered-properties.tsx",
  "app/(root)/(student)/s-filtered-properties.tsx",
  "app/(root)/(tabs)/all-locations.tsx",
  "app/(root)/(student)/s-all-locations.tsx",
  "app/(root)/(tabs)/properties-by-location.tsx",
  "app/(root)/(student)/s-properties-by-location.tsx",
  "app/(root)/(student)/s-explore.tsx",
  "components/popularLocations.tsx",
  "app/(root)/(tabs)/explore.tsx",
];

for (const relativePath of requiredDiscoveryFiles) {
  const content = outputs[relativePath];

  if (
    !content.includes("cacheKey") ||
    !content.includes("watchCollections")
  ) {
    throw new Error(
      `Validation failed: ${relativePath} lacks a stable change-aware cache.`,
    );
  }
}

if (
  outputs[
    "app/(root)/(student)/s-explore.tsx"
  ].includes("setLoading(true)") ||
  outputs[
    "app/(root)/(tabs)/all-locations.tsx"
  ].includes("useEffect(() =>") ||
  outputs[
    "app/(root)/(tabs)/filtered-properties.tsx"
  ].includes("fetchFilteredProperties")
) {
  throw new Error(
    "Validation failed: an old mount-driven loading workflow remains.",
  );
}

if (
  !outputs[
    "app/(root)/(tabs)/properties-by-location.tsx"
  ].includes('cachePolicy="memory-disk"')
) {
  throw new Error(
    "Validation failed: city-result image caching is missing.",
  );
}

// ===========================================================================
// Back up and write only after every validation succeeds.
// ===========================================================================
for (const [relativePath, content] of Object.entries(outputs)) {
  const absolutePath = path.join(root, relativePath);

  fs.mkdirSync(path.dirname(absolutePath), {
    recursive: true,
  });

  if (fs.existsSync(absolutePath)) {
    fs.copyFileSync(
      absolutePath,
      `${absolutePath}.step12.bak`,
    );
  }

  fs.writeFileSync(absolutePath, content, "utf8");
}

console.log("");
console.log("Step 12 applied successfully.");
console.log("");
console.log("Cold-start persistent query prewarming added.");
console.log("Discovery screens converted to stable Realtime caches.");
console.log("");
console.log("Covered:");
console.log("- Tenant Explore and search/filter combinations");
console.log("- Student Explore");
console.log("- Tenant and student filtered lists");
console.log("- Popular Locations");
console.log("- All Locations");
console.log("- Properties by city");
console.log("- Map pin data");
console.log("");
console.log("Now run: npx tsc --noEmit");
